  info: '#94a3b8',
  unknown: '#cbd5e1',
}

const SEVERITY_ORDER = [
  'critical',
  'high',
  'medium',
  'low',
  'info',
  'unknown',
]

function SectionTitle({ children }) {
  return (
    <h2
      style={{
